    ---------------------------------------------------------------- About
    ABOUT = "關於",
    ABOUT_DESC = "版本、連結和致謝。",
    ABOUT_BYLINE = "作者：%s",
    ABOUT_TEXT = "Phoenix UI 構建在暴雪介面之上，而非取而代之：佈局仍由編輯模式掌控，Phoenix 在其上增添風格與便利。它只重新美化安全框架，從不重建，因此輕量且能避免大部分汙染（taint）；框架移動模組則負責一小份經過驗證、編輯模式無法調整的框架。",
