    SLASH_HELP_TEXT = "/pui – 開啟設定\n/pui edit – 編輯模式\n/pui bugs – 錯誤檢視器（/pui bugs clear、/pui bugs options）\n/pui movers – 解鎖或鎖定框架移動\n/pui profile <名稱> – 切換設定檔\n/pui reset – 重置視窗位置\n/pui <模組> – 跳轉到模組\n/gg – 競技場投降（PvP 模組）",
    RECOMMENDED = "推薦插件",
    RECOMMENDED_TEXT = "2.0 中移除的功能更適合交給為「至暗之夜」持續維護的專門插件：隊伍查詢器過濾用 Premade Groups Filter，滾動戰鬥文字用 MikScrollingBattleText。移動框架是編輯模式的工作；框架移動模組覆蓋它不管理的少數框架。隊友冷卻和光環覆蓋類監控受 12.x 機密數值限制；你自己的冷卻由暴雪冷卻管理器負責。",
